import{_ as t,o,c as a,a3 as r}from"./chunks/framework.DWfJTVRq.js";const p=JSON.parse('{"title":"Electron","description":"Node.js 패키지는 Electron의 메인 프로세스에서도 Node.js에서처럼 같은 애드온으로 동작합니다. Node-API는 Node.js와 Electron 버전이 바뀌어도 그대로이기 때문입니다.","frontmatter":{"title":"Electron","order":12,"languages":["node"],"prev":{"text":"비동기 API","link":"/ko/guide/async"},"next":{"text":"엔진의 구조","link":"/ko/engine/architecture"}},"headers":[{"level":2,"title":"데이터베이스를 열 곳","slug":"데이터베이스를-열-곳","link":"#데이터베이스를-열-곳","children":[]},{"level":2,"title":"앱 인스턴스가 여럿일 때","slug":"앱-인스턴스가-여럿일-때","link":"#앱-인스턴스가-여럿일-때","children":[]},{"level":2,"title":"패키징","slug":"패키징","link":"#패키징","children":[]}],"relativePath":"ko/guide/electron.md","filePath":"ko/guide/electron.md","lastUpdated":1791000973000}'),l={name:"ko/guide/electron.md"};function n(c,e,d,i,s,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="electron" tabindex="-1">Electron <a class="header-anchor" href="#electron" aria-label="Permalink to &quot;Electron&quot;">​</a></h1><p>Node.js 패키지는 Electron의 메인 프로세스에서도 Node.js에서처럼 같은 애드온으로 동작합니다. Node-API는 Node.js와 Electron 버전이 바뀌어도 그대로이기 때문입니다.</p><h2 id="데이터베이스를-열-곳" tabindex="-1">데이터베이스를 열 곳 <a class="header-anchor" href="#데이터베이스를-열-곳" aria-label="Permalink to &quot;데이터베이스를 열 곳&quot;">​</a></h2><p>데이터베이스는 메인 프로세스나 직접 만든 유틸리티 프로세스(<code>utilityProcess</code>)에서 열고, 렌더러에는 IPC로 필요한 것만 건넵니다. 렌더러는 기본으로 샌드박스 안에서 돌아서 네이티브 애드온을 불러올 수 없습니다. 패키지의 테스트는 Electron 44에서 돌립니다.</p><h2 id="앱-인스턴스가-여럿일-때" tabindex="-1">앱 인스턴스가 여럿일 때 <a class="header-anchor" href="#앱-인스턴스가-여럿일-때" aria-label="Permalink to &quot;앱 인스턴스가 여럿일 때&quot;">​</a></h2><p>앱 인스턴스 둘을 포함해 여러 프로세스가 한 파일을 함께 열 수 있습니다. 프로세스마다 제 핸들로 열고, 엔진은 운영체제의 파일 잠금으로 이들을 조율합니다. 쓰기는 한 번에 하나이고, 바쁨 대기 시간보다 오래 기다린 쓰기는 <code>BUSY</code>로 실패합니다. 한 프로세스 안에서 같은 파일을 다시 열면 같은 데이터베이스의 핸들이 하나 더 생깁니다. 잠금 때문에 지킬 규칙은 <a href="./processes">여러 프로세스</a>에 있습니다.</p><h2 id="패키징" tabindex="-1">패키징 <a class="header-anchor" href="#패키징" aria-label="Permalink to &quot;패키징&quot;">​</a></h2><p>패키징한 앱은 애드온을 <code>asar</code> 아카이브 밖에 두는 게 좋습니다. Electron은 아카이브 안의 네이티브 애드온을 밖으로 복사한 뒤에야 불러옵니다. electron-builder는 알아서 밖에 두고, Electron Forge는 auto-unpack-natives 플러그인으로 그렇게 합니다.</p>',8)])])}const _=t(l,[["render",n]]);export{p as __pageData,_ as default};
